import{j as e,D as o,r as a,a as c,L as p}from"./index-DrHRWwF_.js";import{C as m,a as x,L as g}from"./CadrePagePublique-YtgIwTjZ.js";const v=[{id:"champ",titre:"À qui s’applique cette politique"},{id:"donnees",titre:"Ce que le logiciel traite"},{id:"fondements",titre:"Pourquoi, et sur quel fondement"},{id:"temoins",titre:"Témoins et stockage local"},{id:"ne-fait-pas",titre:"Ce que le logiciel ne fait pas"},{id:"hebergement",titre:"Où vos données sont hébergées"},{id:"conservation",titre:"Combien de temps elles sont conservées"},{id:"protection",titre:"Comment elles sont protégées"},{id:"violation",titre:"Si vos données étaient exposées"},{id:"droits",titre:"Vos droits"},{id:"mineurs",titre:"Les mineurs"},{id:"modifications",titre:"Modifications"},{id:"contact",titre:"Nous contacter"}],l=t=>`politique-${t}`;function n({id:t,children:i}){return e.jsx("h2",{id:l(t),tabIndex:-1,className:"text-[12px] font-bold mt-5 mb-1.5 scroll-mt-4 outline-none",children:i})}function h(){return e.jsxs("nav",{"aria-label":"Sommaire de la politique",className:"ecran-seul border border-border px-3 py-2 mb-3",children:[e.jsx("p",{className:"text-[11px] font-semibold text-text-dim mb-1",children:"Sommaire"}),e.jsx("ol",{className:"text-[11.5px] leading-relaxed list-decimal pl-5 sm:columns-2",children:v.map(t=>e.jsx("li",{children:e.jsx("button",{type:"button",onClick:()=>{const i=document.getElementById(l(t.id));i==null||i.scrollIntoView({block:"start"}),i==null||i.focus({preventScroll:!0})},className:"text-sel underline text-left",children:t.titre})},t.id))})]})}function s({children:t}){return e.jsx("p",{className:"text-[11.5px] leading-relaxed mb-2",children:t})}function q(){return e.jsx(x,{titre:"Politique de confidentialité d’OmegaX",sousTitre:`Dernière mise à jour · ${o}`,children:e.jsx(d,{})})}function b(){return e.jsx(m,{sousTitre:`Dernière mise à jour · ${o}`,children:e.jsx(d,{})})}function d(){const[t,i]=a.useState(!1);return a.useEffect(()=>{let r=!0;return c.get("/sur-site/etat").then(u=>r&&i(u.surSite)).catch(()=>{}),()=>{r=!1}},[]),e.jsxs(e.Fragment,{children:[e.jsxs(s,{children:["OmegaX est un logiciel de comptabilité destiné aux associations sans but lucratif, aux organisations non gouvernementales et aux entreprises de la République démocratique du Congo. Il est édité et exploité par le cabinet ",e.jsx("strong",{children:"VMG Consulting"}),", qui est le responsable du traitement des données décrites ci-dessous."]}),e.jsxs("div",{className:"border-l-4 border-[var(--a-700)] bg-[var(--a-50)] px-3 py-2 mb-3",children:[e.jsx("p",{className:"text-[11.5px] font-bold mb-1",children:"Notre engagement"}),e.jsx("p",{className:"text-[11.5px] leading-relaxed",children:"Vos dossiers comptables vous appartiennent. Nous ne vendons ni ne louons aucune donnée, nous n’en faisons aucun usage publicitaire, et nous ne consultons pas le contenu de vos dossiers. Nous ne communiquons vos données qu’aux prestataires désignés à la section 6, pour vous rendre le service, ou sur réquisition judiciaire. Cette page dit ce que le logiciel fait réellement · chaque affirmation y est vérifiable dans son code."})]}),e.jsx(h,{}),e.jsx(n,{id:"champ",children:"1. À qui s’applique cette politique"}),e.jsx(s,{children:"Elle vise six catégories de personnes :"}),e.jsxs("ul",{className:"text-[11.5px] leading-relaxed mb-2 list-disc pl-5",children:[e.jsxs("li",{children:[e.jsx("strong",{children:"Les visiteurs"})," des pages publiques d’OmegaX · écran d’ouverture, page de présentation, questions fréquentes, contrat de licence et la présente politique."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Les personnes qui demandent un essai gratuit"})," par le formulaire d’essai."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Les utilisateurs"})," des dossiers · comptables, aides-comptables, gestionnaires de paie, administrateurs et lecteurs, qu’ils appartiennent à un cabinet ou à l’entité tenue."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Les cabinets et entités clientes"}),", signataires du contrat de licence."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Les personnes dont les données figurent dans un dossier"})," · salariés, fournisseurs, clients, membres, donateurs. Pour elles, c’est l’entité qui tient le dossier qui est responsable du traitement ; VMG Consulting n’agit que pour son compte (section 2)."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Les opérateurs de la console"})," de VMG Consulting."]})]}),e.jsx(n,{id:"donnees",children:"2. Ce que le logiciel traite"}),e.jsx(s,{children:"OmegaX traite deux catégories de données, et deux seulement."}),e.jsxs(s,{children:[e.jsx("strong",{children:"Les données de vos dossiers comptables"})," · plan de comptes, journaux, écritures, tiers, immobilisations, budgets, états financiers et pièces que vous y saisissez. Elles vous appartiennent. Elles peuvent contenir des données personnelles si vous en saisissez (nom d’un fournisseur, d’un membre, d’un salarié) : dans ce cas, c’est votre entité qui en est responsable, et VMG Consulting n’agit que comme sous-traitant, pour votre compte et sur vos instructions."]}),e.jsxs(s,{children:[e.jsx("strong",{children:"Les données de compte et de traçabilité"})," · l’adresse de courriel et le rôle de chaque utilisateur, l’empreinte chiffrée de son mot de passe (jamais le mot de passe lui-même) et, si la double authentification est activée, le secret de l’application d’authentification et l’empreinte des codes de secours. S’y ajoute le journal d’audit, qui enregistre qui a fait quoi et quand dans le dossier, chaque connexion réussie, et l’",e.jsx("strong",{children:"adresse réseau (adresse IP)"})," d’où chaque acte a été fait. Ce journal n’est pas une option : les textes comptables applicables (Acte uniforme relatif au droit comptable, art. 22) imposent que l’origine et l’imputation de chaque écriture puissent être restituées, et le Code du numérique (article 219, 14°) veut que l’on puisse constater après coup qui a eu accès aux données personnelles, et quand."]}),e.jsxs(s,{children:[e.jsx("strong",{children:"La demande d’essai"})," · le type de l’entité, son nom et l’adresse de courriel donnée. Ils servent à ouvrir le dossier d’essai et à envoyer à cette adresse, et à elle seule, le mot de passe provisoire. L’adresse réseau d’où part la demande sert à limiter leur nombre · le serveur d’application ne l’inscrit dans aucune table ; son limiteur en garde une empreinte en mémoire tant que le service tourne. Comme pour toute requête, l’hébergeur (Google Cloud Run) inscrit l’adresse dans ses journaux techniques."," ",e.jsx("em",{children:"La durée de conservation de ces journaux doit être arrêtée par VMG Consulting et portée ici avant toute publication de cette page sur un magasin d’applications."})]}),e.jsx(n,{id:"fondements",children:"3. Pourquoi, et sur quel fondement"}),e.jsxs(s,{children:["Le Code du numérique (ordonnance-loi n° 23/10 du 13 mars 2023) n’admet que deux fondements à un traitement de données personnelles · le ",e.jsx("strong",{children:"consentement"})," de la personne concernée, ou une"," ",e.jsx("strong",{children:"obligation légale"})," du responsable du traitement (article 192). Voici lequel porte chaque traitement d’OmegaX."]}),e.jsx("div",{className:"overflow-x-auto mb-2",children:e.jsxs("table",{className:"text-[11.5px] w-full",children:[e.jsx("thead",{children:e.jsxs("tr",{children:[e.jsx("th",{className:"text-left",children:"Traitement"}),e.jsx("th",{className:"text-left",children:"Pourquoi"}),e.jsx("th",{className:"text-left",children:"Fondement"})]})}),e.jsxs("tbody",{children:[e.jsxs("tr",{children:[e.jsx("td",{children:"Données de vos dossiers"}),e.jsx("td",{children:"Tenir votre comptabilité"}),e.jsx("td",{children:"Celui que votre entité, responsable, retient ; VMG Consulting agit sur ses instructions (article 229)"})]}),e.jsxs("tr",{children:[e.jsx("td",{children:"Journal d’audit, adresse IP de chaque acte"}),e.jsx("td",{children:"Restituer l’origine de chaque écriture, constater qui a eu accès aux données"}),e.jsx("td",{children:"Obligation légale · Acte uniforme relatif au droit comptable, art. 22 ; Code du numérique, article 219, 14°"})]}),e.jsxs("tr",{children:[e.jsx("td",{children:"Sauvegarde de la base"}),e.jsx("td",{children:"Pouvoir restaurer vos dossiers"}),e.jsx("td",{children:"Obligation légale · Code du numérique, articles 219, 15° et 221"})]}),e.jsxs("tr",{children:[e.jsx("td",{children:"Compte utilisateur et connexion"}),e.jsx("td",{children:"Vous identifier et protéger l’accès"}),e.jsx("td",{children:"Consentement, donné en ouvrant votre compte ou en acceptant l’accès que votre administrateur vous ouvre"})]}),e.jsxs("tr",{children:[e.jsx("td",{children:"Demande d’essai"}),e.jsx("td",{children:"Ouvrir le dossier d’essai et vous remettre l’accès"}),e.jsx("td",{children:"Consentement, donné en envoyant le formulaire"})]}),e.jsxs("tr",{children:[e.jsx("td",{children:"Mesure de fréquentation et erreurs de l’interface"}),e.jsx("td",{children:"Savoir quels écrans servent, corriger les pannes"}),e.jsx("td",{children:"Consentement, demandé avant tout envoi et retirable à tout moment (section 4)"})]})]})]})}),e.jsx(s,{children:"Sans adresse de courriel, aucun compte ne peut être ouvert ni aucun accès remis ; la demande d’essai exige en outre le type et le nom de l’entité (article 220, 7°). Refuser la mesure de fréquentation ne change rien au fonctionnement du logiciel."}),e.jsx(n,{id:"temoins",children:"4. Témoins et stockage local"}),e.jsxs(s,{children:["OmegaX ne dépose ",e.jsx("strong",{children:"aucun traceur publicitaire"}),".",t?" Sur cette installation, il ne mesure pas la fréquentation et ne signale aucune erreur à un service extérieur.":" Il peut mesurer la fréquentation de son interface, sans votre nom ni le contenu de vos dossiers, et signaler ses erreurs techniques (section 6), seulement si vous l’acceptez · la question vous est posée par un bandeau avant tout envoi. Avec votre accord, le navigateur garde dans son stockage local un identifiant tiré au hasard, sans lien avec votre compte ni avec votre dossier."," ","Le seul témoin de connexion déposé est celui de votre session : il est strictement nécessaire au fonctionnement du logiciel, et il n’est pas lisible par le code de la page. Sans l’option « Rester connecté sur cet appareil », il se ferme avec le navigateur, et la session prend fin au plus tard au terme de la durée de session du service, huit heures par défaut, après la connexion. Avec cette option, la session dure trente jours au plus depuis la connexion, et se ferme après sept jours sans utilisation. La console de l’éditeur redemande le mot de passe et le code huit heures après la dernière connexion complète."]}),e.jsx(s,{children:"Votre navigateur garde aussi, dans son stockage local et sur cet appareil seulement, la liste des cinq dossiers ouverts le plus récemment (nom du dossier, adresse de connexion, date), qui préremplit l’adresse à l’ouverture, le jeton qui protège vos envois contre la falsification de requête, et vos préférences d’affichage (exercice choisi, favoris de l’accueil, onglets). Rien de cela n’est transmis à un tiers ; effacer les données de ce site dans le navigateur le supprime."}),!t&&e.jsxs(s,{children:["Votre réponse au bandeau est gardée dans ce même stockage local, avec sa date. Pour la changer, utilisez"," ",e.jsx(p,{className:"text-sel underline"}),", en bas de cette page et de l’écran d’ouverture · retirer votre accord est aussi simple que de le donner (article 196)."]}),e.jsx(n,{id:"ne-fait-pas",children:"5. Ce que le logiciel ne fait pas"}),e.jsxs(s,{children:["Vos données comptables ne sont ",e.jsx("strong",{children:"ni revendues, ni cédées, ni exploitées à d’autres fins"})," que de vous rendre le service. Elles ne servent pas à entraîner de modèle statistique. Aucune décision automatisée n’est prise à votre sujet."]}),e.jsxs(s,{children:["OmegaX ne fait ",e.jsx("strong",{children:"aucune prospection"})," · vos données ne servent ni à vous adresser de la publicité, ni à en adresser à vos tiers, et ne sont communiquées à aucun partenaire commercial."]}),e.jsx(n,{id:"hebergement",children:"6. Où vos données sont hébergées"}),t?e.jsxs(e.Fragment,{children:[e.jsxs(s,{children:["Cette installation d’OmegaX est ",e.jsx("strong",{children:"installée sur un ordinateur de votre entité"}),". La base de données, le serveur d’application et l’interface y tournent tous les trois : vos dossiers comptables restent sur cet ordinateur et ne sont confiés à aucun hébergeur. VMG Consulting n’y a pas accès."]}),e.jsx(s,{children:"Un courriel ne part du logiciel (relance, avis d’accès) que si votre entité a configuré une messagerie sur ce poste · le prestataire qu’elle a choisi reçoit alors l’adresse du destinataire et le texte du courrier."}),e.jsxs(s,{children:[e.jsx("strong",{children:"Aucune erreur technique ni aucune page vue ne quitte cette installation"})," : les services de mesure utilisés par la version en ligne (Sentry, PostHog) n’y sont pas activés."]})]}):e.jsxs(e.Fragment,{children:[e.jsx(s,{children:"Sept prestataires interviennent, chacun pour une part précise :"}),e.jsxs("ul",{className:"text-[11.5px] leading-relaxed mb-2 list-disc pl-5",children:[e.jsxs("li",{children:[e.jsx("strong",{children:"Neon"})," héberge la base de données PostgreSQL qui contient vos dossiers comptables."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Google Cloud Run"}),", dans la région ",e.jsx("strong",{children:"us-east1"})," (Caroline du Sud, États-Unis d’Amérique), exécute le serveur d’application qui lit et écrit dans cette base."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Firebase Hosting"})," sert l’interface, c’est à dire les pages et les scripts que votre navigateur affiche, et relaie vos requêtes vers le serveur. Aucune donnée comptable n’y est stockée."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"GitHub"})," (service GitHub Actions) produit chaque nuit la sauvegarde de la base et la conserve, chiffrée (section 7). Une copie de ce fichier chiffré est déposée chaque nuit dans"," ",e.jsx("strong",{children:"Google Cloud Storage"}),", dans la région ",e.jsx("strong",{children:"europe-west1"})," (Belgique)."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Le prestataire de messagerie"})," (SMTP) retenu par VMG Consulting reçoit l’adresse du destinataire et le texte des courriers que le logiciel envoie à votre demande · relances, factures, licences, avis d’accès. ",e.jsx("em",{children:"Son nom doit être arrêté par VMG Consulting et porté ici avant toute publication de cette page sur un magasin d’applications."})]}),e.jsxs("li",{children:[e.jsx("strong",{children:"Sentry"}),", dans sa région de données de l’",e.jsx("strong",{children:"Union européenne"}),", reçoit les erreurs techniques du serveur et, avec votre accord seulement (section 4), de l’interface · le type de l’erreur, l’endroit du code où elle est survenue, l’écran ou la route en cause, le navigateur et sa version. S’y ajoutent le fil des dernières requêtes réduit à leur méthode, leur adresse sans identifiants ni paramètres et leur statut, les écrans ouverts juste avant, et la version publiée du logiciel."]}),e.jsxs("li",{children:[e.jsx("strong",{children:"PostHog"}),", dans sa région de données de l’",e.jsx("strong",{children:"Union européenne"}),", reçoit les pages vues de l’interface, sans votre nom ni le contenu de vos dossiers et avec votre accord seulement (section 4) · l’écran ouvert, le rôle de l’utilisateur (comptable, administrateur…), le référentiel du dossier (SYCEBNL ou SYSCOHADA), le navigateur et la taille de l’écran. S’y ajoutent le système d’exploitation, le fuseau horaire, le type d’appareil, l’adresse du site et des identifiants de session tirés au hasard ; aucune localisation n’est déduite de l’adresse réseau."]})]}),e.jsxs(s,{children:["Ni Sentry ni PostHog ne reçoivent ",e.jsx("strong",{children:"jamais"})," de donnée de vos dossiers : aucun montant, aucun nom, aucune adresse de courriel, aucun contenu saisi, aucun libellé, aucun numéro de pièce, aucun témoin de connexion. Les identifiants et les nombres sont retirés des adresses des écrans avant l’envoi, les messages d’erreur sont réduits à leur forme, et aucun enregistrement de votre session n’est fait. Comme toute connexion, ces deux services voient passer l’adresse réseau qui leur écrit."," ",e.jsx("em",{children:"Le réglage qui leur interdit de la conserver doit être activé par VMG Consulting dans chacun des deux services avant toute publication de cette page sur un magasin d’applications."})]}),e.jsxs(s,{children:["Vos données sont donc ",e.jsx("strong",{children:"hébergées hors de la République démocratique du Congo"}),". Ce point est énoncé ici parce qu’il vous appartient de le connaître et, le cas échéant, de vérifier qu’il est compatible avec les engagements pris envers vos propres bailleurs de fonds."]}),e.jsxs(s,{children:["Le Code du numérique congolais (ordonnance-loi n° 23/10 du 13 mars 2023) pose à son article 201 que les données personnelles sont stockées ou hébergées en République démocratique du Congo, et qu’un transfert vers un État tiers suppose l’autorisation préalable de l’Autorité de protection des données ; son article 202 énumère les cas où un tel transfert reste possible. ",e.jsx("strong",{children:"La base juridique du transfert opéré ici est en cours de qualification."})," Pour les données personnelles de vos dossiers, dont votre entité est responsable, le transfert relève de ses instructions, VMG Consulting agissant pour son compte (article 229)."]})]}),e.jsx(n,{id:"conservation",children:"7. Combien de temps elles sont conservées"}),t?e.jsx(s,{children:"Vos dossiers comptables restent sur cet ordinateur aussi longtemps que votre entité les y garde, et la durée légale de conservation des documents comptables s’impose à elle : les états financiers et les pièces qui les justifient doivent rester présentables après la clôture."}):e.jsx(s,{children:"Vos dossiers comptables sont conservés pendant toute la durée de votre abonnement, puis pendant la durée légale de conservation des documents comptables. Ce n’est pas un choix commercial : les états financiers et les pièces qui les justifient doivent rester présentables après la clôture."}),e.jsxs(s,{children:["Les ",e.jsx("strong",{children:"données de compte et le journal d’audit"})," ne sont soumis à aucune purge. Un compte utilisateur se désactive, il ne se supprime pas ; le journal, dont chaque événement porte l’empreinte du précédent, garde le courriel et l’adresse IP de l’auteur de chaque acte tant que le dossier existe.",!t&&e.jsxs("em",{children:[" ","Leur durée de conservation doit être arrêtée par VMG Consulting et portée ici avant toute publication de cette page sur un magasin d’applications."]})]}),t?e.jsxs(s,{children:["Une ",e.jsx("strong",{children:"sauvegarde"})," de la base est produite chaque jour sur cet ordinateur, et les trente plus récentes sont gardées, sauf réglage différent de votre installation. Une copie peut en être déposée hors du poste, ",e.jsx("strong",{children:"chiffrée"})," par une phrase secrète que choisit l’administrateur de l’installation · sans elle, la copie ne se relit pas, et VMG Consulting ne la détient pas."]}):e.jsxs(s,{children:["Une ",e.jsx("strong",{children:"sauvegarde chiffrée"})," de la base est produite chaque nuit. Elle est chiffrée avant de quitter le serveur qui la produit, et VMG Consulting est seul à détenir la clé qui permet de la lire. Le fichier est conservé quatre-vingt-dix jours par GitHub ; sa copie déposée dans Google Cloud Storage (europe-west1) n’a pas de durée fixée par le logiciel."," ",e.jsx("em",{children:"La durée de conservation de cette copie doit être arrêtée par VMG Consulting et portée ici avant toute publication de cette page sur un magasin d’applications."})]}),!t&&e.jsxs(s,{children:["Un ",e.jsx("strong",{children:"dossier d’essai"})," arrivé à son terme passe en lecture seule · ses données restent consultables, rien ne s’y écrit plus."," ",e.jsx("em",{children:"La durée au-delà de laquelle un dossier d’essai non souscrit est supprimé doit être arrêtée par VMG Consulting et portée ici avant toute publication de cette page sur un magasin d’applications."})]}),e.jsx(n,{id:"protection",children:"8. Comment elles sont protégées"}),t?e.jsxs(s,{children:["Sur cette installation, les échanges entre les postes du bureau et l’ordinateur qui porte OmegaX passent en ",e.jsx("strong",{children:"http, sur le réseau local"})," de votre entité : OmegaX ne les chiffre pas. Le service n’est ouvert qu’aux réseaux privés et de domaine par la règle de pare-feu posée à l’installation."]}):e.jsxs(s,{children:["Les échanges entre votre navigateur et le service sont ",e.jsx("strong",{children:"chiffrés en transit (HTTPS)"})," ","jusqu’au relais Firebase Hosting, qui les transmet au serveur d’application. Ce n’est pas un chiffrement de bout en bout : le relais les déchiffre pour les acheminer."]}),e.jsx(s,{children:"Chaque dossier est cloisonné des autres au niveau de chaque requête du serveur : une requête qui ne porte pas la borne de votre dossier est refusée par le logiciel, elle n’est pas corrigée en silence. Les mots de passe ne sont jamais stockés en clair. Les tentatives de connexion répétées sont ralenties, et une session est révoquée dès qu’un mot de passe change, qu’un accès est retiré ou qu’un rôle est modifié."}),e.jsxs(s,{children:[e.jsx("strong",{children:"VMG Consulting ne consulte pas le contenu de vos dossiers."})," Ses accès techniques à la base se limitent à la sauvegarde chiffrée de chaque nuit, dont elle détient la clé, à la restauration de contrôle automatique qui l’éprouve et ne rend que des décomptes et le contrôle de l’équilibre des écritures, et aux requêtes de maintenance, qui ne rendent que des identifiants et des nombres, jamais un montant, un compte, un objet ni un motif. Sa console d’exploitation ne montre d’un dossier que sa fiche commerciale et sa licence ; une correction de dossier se fait par vous, dans votre dossier. Le mot de passe provisoire d’un administrateur, tiré au sort par le serveur, part à sa seule adresse électronique. Le fournisseur de services numériques reste tenu à la confidentialité des données qu’il traite, sauf réquisition judiciaire (Code du numérique, article 37)."]}),e.jsx(n,{id:"violation",children:"9. Si vos données étaient exposées"}),t?e.jsxs(s,{children:["Sur cette installation, VMG Consulting n’a accès à aucune donnée. L’article 244 du Code du numérique met la notification d’une violation, ",e.jsx("strong",{children:"sans délai"}),", à l’Autorité de protection des données et aux personnes concernées, à la charge du responsable du traitement · votre entité, pour les données qu’elle tient sur cet ordinateur."]}):e.jsxs(e.Fragment,{children:[e.jsxs(s,{children:["L’article 244 du Code du numérique distingue deux obligations. Pour les"," ",e.jsx("strong",{children:"données de compte et de traçabilité"}),", dont VMG Consulting est responsable, nous notifierons ",e.jsx("strong",{children:"sans délai"}),", à l’Autorité de protection des données et à vous-même, toute violation les ayant affectées (alinéa 1er)."]}),e.jsxs(s,{children:["Pour les ",e.jsx("strong",{children:"données personnelles de vos dossiers"}),", dont votre entité est responsable, VMG Consulting, sous-traitant, vous avertira ",e.jsx("strong",{children:"sans délai"})," de toute atteinte à leur sécurité (alinéa 2) · il revient alors à votre entité de notifier l’Autorité et les personnes concernées (alinéa 1er). Dans les deux cas, nous vous dirons ce qui a été atteint, quand, et ce que nous avons fait, plutôt que de vous adresser une formule."]})]}),e.jsx(n,{id:"droits",children:"10. Vos droits"}),e.jsxs(s,{children:["Vous pouvez demander à consulter, corriger, exporter ou supprimer les données qui vous concernent. L’export de vos dossiers est d’ailleurs prévu dans le logiciel : les états financiers, la liasse complète et les livres obligatoires s’exportent au format tableur sans avoir à nous le demander, et",e.jsx("strong",{children:" Fichier > Restituer le dossier complet"})," en produit une archive, table par table, en un seul fichier, sous les cinq réserves qu’elle écrit elle-même (elle ne remplace notamment pas la conservation des pièces justificatives)."]}),e.jsx(s,{children:"L’effacement cède devant une obligation légale qui impose de conserver les données (article 216) ; son articulation avec la conservation des documents comptables et du journal d’audit est en cours de qualification. Vous pouvez aussi définir les modalités de la gestion de vos données personnelles après votre mort (article 208), et vous avez le droit d’introduire une réclamation auprès de l’autorité chargée de la protection des données à caractère personnel et de former un recours juridictionnel (articles 220 et 239)."}),e.jsxs(s,{children:["Le traitement que VMG Consulting fait des données de vos dossiers pour le compte de votre entité est réglé par l’article 9 du ",e.jsx(g,{chemin:"/contrat-de-licence",children:"contrat de licence"}),", comme le veut l’article 229 du Code du numérique."]}),e.jsxs(s,{children:["Pour toute autre demande, écrivez à VMG Consulting à l’adresse"," ",e.jsx("a",{href:"mailto:admin@vmgconsulting.net",className:"text-sel underline",children:"admin@vmgconsulting.net"})," ","(adresse arrêtée par VMG Consulting le 17 octobre 2026). ",e.jsx("em",{children:"L’adresse postale du cabinet doit être arrêtée par VMG Consulting et portée ici avant toute publication de cette page sur un magasin d’applications."})," ","Elle n’est pas inscrite d’office : une adresse inventée dirigerait vos demandes vers le vide."]}),e.jsxs(s,{children:[e.jsx("strong",{children:"Délais."})," Nous vous disons la suite donnée à votre demande dans les"," ",e.jsx("strong",{children:"trente jours"})," de sa réception (articles 213, 214 et 239). L’article 239 permet de prolonger ce délai de soixante jours au plus quand la demande est complexe ; nous vous le dirions alors, avec le motif, dans les trente premiers jours. La copie de vos données vous est remise au plus tard soixante jours après la demande (article 210). La réponse est gratuite (article 240) ; nous pouvons vous demander de quoi confirmer votre identité (article 241)."]}),e.jsx(n,{id:"mineurs",children:"11. Les mineurs"}),e.jsx(s,{children:"OmegaX est un logiciel professionnel, destiné aux entités et à leurs comptables · il n’est pas proposé aux mineurs, et nous n’ouvrons pas de compte à un mineur en connaissance de cause. Un dossier peut néanmoins contenir des données relatives à un mineur, par exemple les enfants à charge d’un salarié au registre du personnel · elles sont traitées pour le compte de l’entité, qui en est responsable. L’article 247 du Code du numérique soumet au consentement du titulaire de la responsabilité parentale le traitement des données d’un mineur à qui un service est offert directement, ce qui n’est pas le cas d’OmegaX."}),e.jsx(n,{id:"modifications",children:"12. Modifications"}),e.jsx(s,{children:"Cette politique peut évoluer avec le logiciel, et la date de sa dernière mise à jour figure en tête de page. Elle fait partie de l’offre de VMG Consulting (Code du numérique, article 53, 10°) · une modification de ce qu’elle engage suit l’article 15 du contrat de licence, c’est-à-dire l’article 34 du Code du numérique · projet communiqué au moins trente jours ouvrables avant son entrée en vigueur."}),e.jsx(n,{id:"contact",children:"13. Nous contacter"}),e.jsxs("div",{className:"border border-border px-3 py-2 mb-2 text-[11.5px] leading-relaxed",children:[e.jsx("p",{className:"font-bold",children:"VMG Consulting"}),e.jsx("p",{children:"Responsable du traitement des données de compte et de traçabilité"}),e.jsxs("p",{className:"mt-1",children:["Courriel ·"," ",e.jsx("a",{href:"mailto:admin@vmgconsulting.net",className:"text-sel underline",children:"admin@vmgconsulting.net"})]}),e.jsx("p",{children:e.jsx("em",{children:"Adresse postale · à arrêter par VMG Consulting (section 10)."})})]}),e.jsx(s,{children:"Si notre réponse ne vous satisfait pas, vous pouvez saisir l’Autorité de protection des données (article 239)."})]})}export{b as ConfidentialiteFenetre,q as ConfidentialitePage,d as ContenuConfidentialite,o as DATE_DE_MISE_A_JOUR,v as SECTIONS_POLITIQUE};
